import json, os, sqlite3
skill_dir = os.path.join(WORKSPACE_ROOT, 'skills', 'report_engine')
config_path = os.path.join(skill_dir, 'config.json')
db_path = os.path.join(WORKSPACE_ROOT, 'data', 'agent.db')
if not os.path.exists(config_path):
    result = {'success': False, 'error': 'No report templates configured'}
else:
    with open(config_path, 'r', encoding='utf-8') as f:
        config = json.load(f)
    template = None
    for t in config.get('templates', []):
        if t['id'] == template_id:
            template = t
            break
    if not template:
        result = {'success': False, 'error': f'Template {template_id} not found'}
    elif not os.path.exists(db_path):
        result = {'success': False, 'error': 'Database does not exist yet'}
    else:
        try:
            params = json.loads(params_json) if params_json else {}
            param_defs = template.get('parameters', {})
            for pname, pdef in param_defs.items():
                if pname not in params and 'default' in pdef:
                    params[pname] = pdef['default']
            sql = template['sql']
            for pname, pval in params.items():
                sql = sql.replace(f'${{{pname}}}', str(pval))
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
            cursor = conn.cursor()
            cursor.execute(sql)
            rows = [dict(row) for row in cursor.fetchall()]
            columns = [desc[0] for desc in cursor.description] if cursor.description else []
            conn.close()
            result = {'success': True, 'template': template['name'], 'data': rows, 'columns': columns, 'row_count': len(rows)}
        except Exception as e:
            result = {'success': False, 'error': str(e)}

import json, os
skill_dir = os.path.join(WORKSPACE_ROOT, 'skills', 'report_engine')
config_path = os.path.join(skill_dir, 'config.json')
if not os.path.exists(config_path):
    result = {'success': True, 'templates': [], 'message': 'No templates configured yet'}
else:
    with open(config_path, 'r', encoding='utf-8') as f:
        config = json.load(f)
    templates = [{'id': t['id'], 'name': t['name'], 'description': t['description'], 'category': t.get('category', 'general'), 'parameters': t.get('parameters', {})} for t in config.get('templates', [])]
    result = {'success': True, 'templates': templates, 'count': len(templates)}
